SELECT DATE_FORMAT(c.signup_date, 'yyyy-MM') AS signup_month, c.is_active, ROUND((100 * SUM(CASE WHEN s.plan = 'basic' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_basic, COUNT(s.monthly_fee) AS monthly_fee_count FROM subscriptions s RIGHT JOIN customers c ON s.customer_id = c.id GROUP BY DATE_FORMAT(c.signup_date, 'yyyy-MM'), c.is_active ORDER BY monthly_fee_count, signup_month, is_active LIMIT 1
